def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    # 1. Sort events by timestamp.
    # For same timestamps, OFFLINE must come before MESSAGE.
    # We use priority 0 for OFFLINE and 1 for MESSAGE to ensure correct ordering.
