        time = int(e[1])
        type_str = e[0]
        priority = 0 if type_str == "OFFLINE" else 1
        sorted_events.append((time, priority, type_str, e[2]))

    sorted_events.sort()

    mentions = [0] * numberOfUsers
    is_online = [True] * numberOfUsers
    # Track when a user will come back online: {user_id: return_time}
    offline_until = {}

    for time, priority, type_str, content in sorted_events:
        # Before processing any event at this timestamp, 
