def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # status stores the time when a user will become online again. 
    # If 0, they are currently online indefinitely (or until an OFFLINE event).
    # We use -1 to represent "always online" and positive integers for offline duration.
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp. For same timestamp, handle OFFLINE first? 
    # The prompt says status changes are processed before messages at the same timestamp.
    # So we sort by time, then type (OFFLINE before MESSAGE).
    sorted_events = sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

    for event in sorted_events:
        etype, timestamp_str, content = event
        timestamp = int(timestamp_str)

        # Update statuses first for any user who might have come back online
        for i in range(numberOfUsers):
            if offline_until[i] > 0 and offline_until[i] <= timestamp:
                offline_until[i] = 0

        if etype == "OFFLINE":
            user_id = int(content.replace("id", ""))
            offline_until[user_id] = timestamp + 60
        elif etype == "MESSAGE":
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                for i in range(numberOfUsers):
                    if offline_until[i] == 0:
                        mentions[i] += 1
            else:
                # Content is a string of ids like "id1 id0"
                tokens = content.split()
                for token in tokens:
                    if token.startswith("id"):
                        uid = int(token[2:])
                        mentions[uid] += 1

    return mentions
