from typing import List

def maxScore(nums: List[int]) -> int:
    def get_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def get_lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // get_gcd(a, b)

    def calculate_score(arr):
        if not arr:
            return 0
        if len(arr) == 1:
            return arr[0] * arr[0]

        current_gcd = arr[0]
        current_lcm = arr[0]
        for i in range(1, len(arr)):
            current_gcd = get_gcd(current_gcd, arr[i])
            current_lcm = get_lcm(current_lcm, arr[i])
        return current_gcd * current_lcm

    # Case: Remove zero elements
    max_score = calculate_score(nums)

    # Case: Remove exactly one element
    # Since nums.length is small (up to 100), we can iterate through all possibilities.
    for i in range(len(nums)):
        temp_nums = nums[:i] + nums[i+1:]
        score = calculate_score(temp_nums)
        if score > max_score:
            max_score = score

    return max_score
